package org.marketreview.nativeapp;
import android.content.Context;
import org.json.*;
import java.io.File;
import java.nio.file.Files;
import java.util.*;
/** Device-only SQLite checks. Compiled in v43, not executed on a device. No worker or platform calls. */
public final class CollectionPublicationChecks {
 interface Work {void run()throws Exception;}
 static boolean rejects(Work work)throws Exception{try{work.run();return false;}catch(Exception e){return true;}}
 static boolean equal(Object a,Object b)throws Exception{return ResearchRuns.canonical(a).equals(ResearchRuns.canonical(b));}
 static JSONObject find(BusinessStore s,String kind,String id)throws Exception{JSONArray rows=s.read(kind);for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("id").equals(id))return rows.getJSONObject(i);return null;}
 static JSONObject job()throws Exception{return new JSONObject().put("id","same-work").put("title","隔离作品").put("text","人工校对稿").put("originalText","原始稿保留").put("status","completed").put("executionRevision","revision-1").put("assetPath","fixture-old-media-never-opened").put("unknownMetadata",new JSONObject().put("retain",true));}
 static JSONObject document(JSONObject job)throws Exception{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(job.getString("id").getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder h=new StringBuilder();for(byte b:bytes)h.append(String.format(Locale.ROOT,"%02x",b&255));return new JSONObject().put("id","collection:"+h.substring(0,40)).put("title",job.getString("title")).put("text",job.getString("text")).put("originalText",job.getString("originalText")).put("collectionId",job.getString("id")).put("verification","unverified");}
 static void check(JSONArray results,boolean pass,String name)throws Exception{results.put(new JSONObject().put("name",name).put("passed",pass));if(!pass)throw new Exception(name);}
 public static JSONObject run(Context context,File directory)throws Exception{
  if(directory.exists()||!directory.getName().startsWith("publication-v43-")||!directory.getCanonicalFile().getParentFile().equals(context.getCacheDir().getCanonicalFile()))throw new Exception("new isolated cache directory required");Files.createDirectory(directory.toPath());JSONArray results=new JSONArray();int serial=0;
  try(BusinessStore s=new BusinessStore(context,new File(directory,(++serial)+".sqlite").getAbsolutePath())){JSONObject before=s.save("collections",job());JSONObject d=CollectionRecords.publish(s,"same-work");check(results,d.getString("text").equals(before.getString("text"))&&d.getString("originalText").equals(before.getString("originalText")),"exact publication through real caller");check(results,equal(before,find(s,"collections","same-work")),"old source/media unchanged");JSONObject human=s.save("docs",d.put("text","研究页人工稿"));check(results,rejects(()->CollectionRecords.publish(s,"same-work"))&&equal(human,find(s,"docs",d.getString("id"))),"existing manual document preserved");}
  for(String field:new String[]{"text","executionRevision","unknownMetadata","delete","peer-document"}){String path=new File(directory,(++serial)+".sqlite").getAbsolutePath();try(BusinessStore s=new BusinessStore(context,path);BusinessStore peer=new BusinessStore(context,path)){JSONObject expected=s.save("collections",job()),d=document(expected);JSONObject human=null;if(field.equals("delete"))peer.getWritableDatabase().delete("records","kind=? AND id=?",new String[]{"collections","same-work"});else if(field.equals("peer-document"))human=peer.save("docs",new JSONObject(d.toString()).put("text","并行人工稿"));else peer.save("collections",new JSONObject(expected.toString()).put(field,"peer change"));check(results,rejects(()->s.commitCollectionPublication(expected,d)),"commit rejects "+field);check(results,human==null?s.read("docs").length()==0:equal(human,find(s,"docs",d.getString("id"))),"peer data preserved "+field);}}
  try(BusinessStore s=new BusinessStore(context,new File(directory,(++serial)+".sqlite").getAbsolutePath())){JSONObject expected=s.save("collections",job());s.getWritableDatabase().execSQL("CREATE TRIGGER fail_publication BEFORE INSERT ON records WHEN NEW.kind='docs' BEGIN SELECT RAISE(ABORT,'fixture publication failure'); END");check(results,rejects(()->CollectionRecords.publish(s,"same-work"))&&s.read("docs").length()==0&&equal(expected,find(s,"collections","same-work")),"insert failure rolls back");s.getWritableDatabase().execSQL("DROP TRIGGER fail_publication");JSONObject d=CollectionRecords.publish(s,"same-work");check(results,d.getString("text").equals(expected.getString("text"))&&s.read("docs").length()==1,"retry publishes same text once without download or ASR");}
  return new JSONObject().put("checks",results.length()).put("results",results).put("platformCalls",0).put("asrProcesses",0).put("provenance","device-fixture-only");
 }
}
